RSpec.describe Timekeeping::LocalOwner do
  # "The generation check runs before receipt replay, so a retry at an old generation gets 409 even when its earlier answer is stored."
  it "answers 409 stale_generation to a retry at the old generation even though its earlier answer is stored" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    old_generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    actor = Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "employee")
    body = { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 1.5, "note" => "retry",
             "source" => TimesheetEntry::SOURCES.first, "source_metadata" => {} }
    params = { "idempotency_key" => "retry-key-1", "body" => body }
    row_counts = lambda do
      %w[entries entry_audits idempotency_records entry_outbox_items].index_with do |table|
        ActiveRecord::Base.connection.select_value("SELECT count(*) FROM #{table}").to_i
      end
    end

    first = described_class.call(operation: :create, company_id: company.id, generation: old_generation.to_s,
                                 actor:, params:)
    expect(first.status).to eq(201)

    TimekeepingOwnership.current.update!(generation: old_generation + 1)
    before_retry = row_counts.call

    retry_outcome = described_class.call(operation: :create, company_id: company.id, generation: old_generation.to_s,
                                         actor:, params:)

    retry_body = retry_outcome.body.is_a?(String) ? JSON.parse(retry_outcome.body) : retry_outcome.body.to_h
    expect(retry_outcome.status).to eq(409)
    expect(retry_body.stringify_keys["reason"].to_s).to eq("stale_generation")
    expect(row_counts.call).to eq(before_retry)
  end
end


