RSpec.describe Timekeeping::LocalOwner do
  # Acceptance bar: "An employee cannot create or edit a colleague's entry through user_id; an owner or admin can for a same-company user"
  it "refuses an employee who names a colleague by a string user_id on create, and lets an admin do it" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil, generation: 1)
    company = create(:company)
    member = lambda do |role|
      user = create(:user)
      create(:employment, company:, user:)
      user.add_role(role, company)
      user
    end
    employee = member.call("employee")
    colleague = member.call("employee")
    admin = member.call("admin")
    project = create(:project, client: create(:client, company:))
    body = {
      "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 60.0, "note" => "x",
      "source" => TimesheetEntry::SOURCES.first, "source_metadata" => {}, "user_id" => colleague.id.to_s
    }
    write = lambda do |actor_user, role, key|
      described_class.call(operation: :create, company_id: company.id, generation: "1",
                           actor: described_class::Actor.user(user_id: actor_user.id, role:),
                           params: { "idempotency_key" => key, "body" => body })
    end

    refused = write.call(employee, "employee", "colleague-by-employee")

    expect(refused.status).to eq(403)
    expect(refused.body["reason"]).to eq("forbidden")
    expect(Timekeeping::LocalEntry.where(company_id: company.id).count).to eq(0)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id).count).to eq(0)
    expect(ActiveRecord::Base.connection.select_value(
      "SELECT COUNT(*) FROM idempotency_records WHERE company_id = #{company.id}"
    ).to_i).to eq(0)

    allowed = write.call(admin, "admin", "colleague-by-admin")

    expect(allowed.status).to eq(201)
    expect(Timekeeping::LocalEntry.where(company_id: company.id).pluck(:user_id)).to eq([colleague.id])
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # Acceptance bar: "A credential nested in an entry body answers credential_in_body and nothing is stored"
  it "answers credential_in_body for a service token nested deep in a create body and stores no row, receipt included" do
    token = "local-owner-held-service-token-#{SecureRandom.hex(16)}"
    previous = ENV["TIMEKEEPING_SERVICE_TOKEN"]
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil, generation: 1)
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role("employee", company)
    project = create(:project, client: create(:client, company:))
    body = {
      "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 60.0, "note" => "x",
      "source" => TimesheetEntry::SOURCES.first, "source_metadata" => { "run" => { "headers" => [{ "auth" => token }] } }
    }
    counts = lambda do
      %w[entries entry_audits idempotency_records entry_outbox_items].map do |table|
        ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i
      end
    end
    before = counts.call

    outcome = described_class.call(operation: :create, company_id: company.id, generation: "1",
                                   actor: described_class::Actor.user(user_id: user.id, role: "employee"),
                                   params: { "idempotency_key" => "credential-key", "body" => body })

    expect(outcome.status).to eq(422)
    expect(outcome.body["reason"]).to eq("credential_in_body")
    # The answer must never echo the secret it refused.
    expect(outcome.body.to_json).not_to include(token)
    expect(counts.call).to eq(before)
  ensure
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = previous
  end
end


RSpec.describe Timekeeping::LocalOwner do
  # Acceptance bar: "The outbox payload's locked field is true when any reservation exists for the entry, whatever entries.locked holds"
  # Issue: "`locked` is true when any reservation row, provisional or committed, exists for the entry in the same company."
  it "publishes locked from reservations, not from entries.locked, when the two disagree" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil, generation: 1)
    company = create(:company)
    owner = create(:user)
    create(:employment, company:, user: owner)
    owner.add_role("owner", company)
    project = create(:project, client: create(:client, company:))
    new_entry = lambda do |locked|
      Timekeeping::LocalEntry.create!(
        company_id: company.id, user_id: owner.id, project_id: project.id, work_date: Date.current,
        duration: 30.0, bill_status: TimesheetEntry.bill_statuses.keys.first, locked:
      )
    end
    reserved_but_unlocked = new_entry.call(false)
    locked_but_unreserved = new_entry.call(true)
    ActiveRecord::Base.connection.execute(<<~SQL)
      INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
      VALUES (#{company.id}, #{reserved_but_unlocked.id}, 1, gen_random_uuid(), 'provisional', 'active', now())
    SQL

    [reserved_but_unlocked, locked_but_unreserved].each do |entry|
      outcome = described_class.call(operation: :update, company_id: company.id, generation: "1",
                                     actor: described_class::Actor.user(user_id: owner.id, role: "owner"),
                                     params: { "idempotency_key" => "locked-#{entry.id}", "entry_id" => entry.id,
                                               "body" => { "note" => "changed" } })
      expect(outcome.status).to eq(200)
    end

    payload_locked = ->(entry) { Timekeeping::LocalOutboxEntry.where(company_id: company.id, entry_id: entry.id).sole.payload["locked"] }
    expect(payload_locked.call(reserved_but_unlocked)).to be(true)
    expect(payload_locked.call(locked_but_unreserved)).to be(false)
  end
end
